    description: 'Уличная Wi-Fi камера Dahua DH-F3D-PV (3 Мп) с активным сдерживанием и Wi-Fi 6. Dahua DH-F3D-PV — это не просто камера наблюдения, а полноценная охранная система в одном корпусе. Главная особенность модели — способность активно отпугивать нарушителей с помощью встроенной сирены и световых сигналов, предотвращая преступление еще до его совершения. Модель идеально подходит для защиты периметра частных домов, парковок и коммерческих объектов: Активное сдерживание (Active Deterrence): При обнаружении постороннего камера включает громкую сирену и красно-синюю (или белую) световую индикацию, оповещая злоумышленника о том, что он обнаружен. Двусторонняя аудиосвязь: Благодаря встроенному микрофону и мощному динамику вы можете общаться с посетителями или курьерами через смартфон из любой точки мира. Разрешение 3 Мп (2304×1296): Высокая детализация изображения позволяет четко фиксировать лица и важные детали. Технология Smart Dual Light: Умная подсветка работает в ИК-режиме, но мгновенно переключается на видимый белый свет при появлении человека для записи цветного видео. Стандарт Wi-Fi 6: Обеспечивает стабильный сигнал без задержек даже на большом расстоянии от роутера и высокую защиту данных. Искусственный интеллект (AI): Точная детекция людей и транспорта исключает ложные срабатывания на животных, деревья или дождь. Матрица: 1/2.8" CMOS с технологией для качественной ночной съемки. Объектив: Широкоугольный 2.8 мм (угол обзора ~103°). Дальность подсветки: До 30 метров. Защита: Класс IP67 (полная защита от пыли и воды, работа до -40°C). Хранение данных: Слот для MicroSD до 256 Гб и поддержка облачного хранилища. Сжатие: H.265 — экономит место на накопителе без потери качества. Почему стоит купить DH-F3D-PV? Это лучший выбор для тех, кому важна проактивная безопасность. Камера не просто записывает инцидент, а активно мешает его развитию. Поддержка Wi-Fi 6 делает её одной из самых технологичных и надежных в своем классе. Закажите Dahua DH-F3D-PV с функцией активного сдерживания и обеспечьте максимальный уровень защиты вашей собственности!',
