    description: 'Уличная Wi-Fi камера Dahua IPC-HFW1339DTK1-SAW-IL 3 Мп с микрофоном. Dahua IPC-HFW1339DTK1-SAW-IL — это надежное и технологичное решение для наружного видеонаблюдения. Камера серии Wi-Fi от Dahua обеспечивает превосходную четкость изображения, умную ночную подсветку и простую установку, что делает её идеальным выбором для охраны частного дома, дачи или территории малого бизнеса. Высокая детализация 3 Мп: Разрешение 2304×1296 позволяет получить более четкую картинку, чем стандартные Full HD камеры, облегчая идентификацию лиц и номеров. Интеллектуальная подсветка Smart Dual Light: Умный ночной режим. Камера ведет съемку в невидимом ИК-диапазоне, но при обнаружении человека включает яркий белый свет и переходит в цветной режим, фиксируя важные детали происшествия. Встроенный микрофон: Поддержка аудиозаписи позволяет не только видеть, но и слышать происходящее на объекте, создавая полную картину событий. Интеллектуальный детектор (AI): Алгоритмы Dahua точно распознают человека в кадре, отфильтровывая ложные тревоги от деревьев, дождя или животных. Стабильный Wi-Fi: Встроенная антенна обеспечивает уверенную передачу сигнала на частоте 2.4 ГГц, позволяя обойтись без прокладки сетевого кабеля. Всепогодная защита IP67: Прочный металлический корпус полностью защищен от пыли и воды. Камера бесперебойно работает в морозы до -40°C и в сильную жару. Матрица: 1/2.7" CMOS с высокой светочувствительностью. Объектив: 2.8 мм (широкий угол обзора ~100°) — идеально для охвата больших территорий. Дальность подсветки: ИК и белый свет до 30 метров. Сжатие данных: Кодеки H.265+ экономят до 70% места на карте памяти без потери качества видео. Хранение: Слот для карт MicroSD до 256 Гб. Удаленный доступ: Простой просмотр через приложение DMSS для iOS и Android. Почему стоит выбрать IPC-HFW1339DTK1-SAW-IL? Цилиндрический форм-фактор с удобным кронштейном позволяет легко направить камеру на нужную зону, а козырек защищает объектив от прямых солнечных лучей и осадков. Технология Smart Dual Light гарантирует, что в случае инцидента ночью у вас будет цветная видеозапись. Купите Dahua IPC-HFW1339DTK1-SAW-IL и обеспечьте профессиональный уровень безопасности вашего участка по доступной цене!',
